code_sketch:
function saveTransaction(tx) {
  let committed = false;
  try {
    apply(tx);                     // may throw at any point
    tx.commit();
    committed = true;
  } finally {
    if (!committed) tx.rollback(); // runs on throw and on early return too
  }
}

